"""Render existing NEP amount-frequency and program recurrence outputs."""
import html,json

def render(data):
    payload=json.dumps({'amounts':data['frequentPrices'],'groups':data['priceGroups']},ensure_ascii=False).replace('</','<\\/')
    content='''<div id="recurring-allocation-amounts"><h3>Other recurring amounts · all DPWH NEP programs</h3><p>₱5M is the most frequent amount in the retained FY2027 output, but other exact allocations recur too. Use the amount filter to inspect their program spread. These are budget allocations, not engineering unit prices; equal amounts do not by themselves establish duplicated scope or overpricing.</p><div class="toolbar"><label>Exact allocation <select id="allocation-amount-filter"><option value="all">All retained amounts</option></select></label><button class="export-btn" id="allocation-frequency-csv">Export amount frequencies CSV</button><button class="export-btn" id="allocation-groups-csv">Export program groups CSV</button></div><p id="allocation-frequency-scope"></p><h4>Most frequent allocations · filtered selection</h4><div id="allocation-frequency-graph"></div><div class="evidence-table"><table><thead><tr><th>NEP year</th><th>Exact allocation</th><th>Budget entries</th><th>Offices</th><th>Program categories</th></tr></thead><tbody id="allocation-frequency-rows"></tbody></table></div><h4>Repeated amounts within programs · filtered selection</h4><div id="allocation-group-graph"></div><div class="evidence-table"><table><thead><tr><th>NEP year</th><th>Program category</th><th>Exact allocation</th><th>Budget entries</th><th>Offices</th><th>Distinct title strings</th></tr></thead><tbody id="allocation-group-rows"></tbody></table></div><p class="caution">The retained frequency output contains 120 ranked amounts, with at least five records per retained amount; the program output contains 279 groups spanning at least three records and three offices. These are filtered outputs, not every allocation amount in the NEP. Distinct title strings are not independently verified distinct projects. Office coverage may overlap between programs. The exact ₱5M road/flood statistical model below applies only to that specified subset; no p-value is transferred to other amounts.</p></div><script id="allocation-amount-data" type="application/json">'''+payload+'''</script><script id="allocation-amount-script">(()=>{
const node=document.getElementById('allocation-amount-data');if(!node)return;const D=JSON.parse(node.textContent),sel=document.getElementById('allocation-amount-filter'),n=v=>Number(v).toLocaleString('en-PH'),peso=v=>'₱'+n(v),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let frequencies=[],groups=[];
for(const amount of [...new Set([...D.amounts,...D.groups].map(r=>Number(r.amount)))].sort((a,b)=>a-b)){const option=document.createElement('option');option.value=String(amount);option.textContent=peso(amount);sel.append(option)}
function graph(id,list,label){const top=list.slice(0,10),max=Math.max(1,...top.map(r=>Number(r.records))),height=top.length*46+20;document.getElementById(id).innerHTML='<svg viewBox="0 0 1100 '+height+'" role="img" aria-label="Top retained records by frequency" style="width:100%;height:auto;max-height:520px">'+top.map((r,i)=>{const title=label(r),display=title.length>58?title.slice(0,55)+'…':title;return '<text x="0" y="'+(i*46+25)+'" font-size="13">'+esc(display)+'</text><rect x="520" y="'+(i*46+8)+'" height="25" width="'+(480*Number(r.records)/max)+'" fill="#087e78"><title>'+esc(title)+' · '+n(r.records)+' entries</title></rect><text x="1020" y="'+(i*46+26)+'" font-size="13">'+n(r.records)+'</text>'}).join('')+'</svg>'}
function rows(id,list,fields){document.getElementById(id).innerHTML=list.map(r=>'<tr>'+fields.map(f=>'<td>'+esc(typeof f==='function'?f(r):r[f])+'</td>').join('')+'</tr>').join('')}
function draw(){const amount=sel.value;frequencies=D.amounts.filter(r=>amount==='all'||Number(r.amount)===Number(amount)).sort((a,b)=>Number(b.records)-Number(a.records));groups=D.groups.filter(r=>amount==='all'||Number(r.amount)===Number(amount)).sort((a,b)=>Number(b.records)-Number(a.records));document.getElementById('allocation-frequency-scope').textContent=frequencies.length+' retained amount rows; '+groups.length+' retained program/amount groups. Graphs show up to ten rows; tables and CSV include the full filtered selection.';graph('allocation-frequency-graph',frequencies,r=>peso(r.amount));graph('allocation-group-graph',groups,r=>peso(r.amount)+' · '+r.category);rows('allocation-frequency-rows',frequencies,['fiscal_year',r=>peso(r.amount),r=>n(r.records),r=>n(r.locations),r=>n(r.categories)]);rows('allocation-group-rows',groups,['fiscal_year','category',r=>peso(r.amount),r=>n(r.records),r=>n(r.locations),r=>n(r.distinct_project_names)])}
function csv(name,list,fields){const content=[fields,...list.map(r=>fields.map(k=>r[k]))].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\\r\\n'),url=URL.createObjectURL(new Blob(['\\ufeff'+content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
sel.onchange=draw;document.getElementById('allocation-frequency-csv').onclick=()=>csv('nep-amount-frequency.csv',frequencies,['fiscal_year','amount','records','locations','categories']);document.getElementById('allocation-groups-csv').onclick=()=>csv('nep-program-amount-groups.csv',groups,['fiscal_year','category','amount','records','locations','distinct_project_names']);draw();})();</script>'''

    return content.replace('120 ranked amounts',str(len(data['frequentPrices']))+' ranked amounts').replace('279 groups',str(len(data['priceGroups']))+' groups')
